n = int(input())
points = []
for _ in range(n):
	points += [tuple(list(map(int, input().split())))]
set_points = set(points)
answered = False
result = 0
if n == 0:
	result = 4
	answered = True
if not answered and n >= 4:
	for i in range(n):
		for j in range(i + 1, n):
			(p_a, p_b) = (points[i], points[j])
			(dx, dy) = (p_a[0] - p_b[0], p_a[1] - p_b[1])
			if (p_b[0] - dy, p_b[1] + dx) in set_points and (p_b[0] + dx - dy, p_b[1] + dx + dy) in set_points or ((p_b[0] + dy, p_b[1] - dx) in set_points and (p_b[0] + dx + dy, p_b[1] - dx + dy) in set_points):
				result = 0
				answered = True
if not answered and n >= 3:
	for i in range(n):
